 <article class="panel action-form-card"><div class="panel-head"><div><span class="section-number">02</span><h2>Inviter un utilisateur</h2><p class="panel-subtitle">Rattachez une personne à une organisation existante.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="action" value="invite"><label class="field"><span>Nom complet</span><input name="user_name" autocomplete="name" placeholder="Nom et prénom"></label><label class="field"><span>Adresse email</span><input type="email" name="email" required autocomplete="email" placeholder="nom@entreprise.com"></label><label class="field"><span>Organisation</span><select name="organization_id" required><option value="">Sélectionner une organisation</option><?php foreach ($organizations as $organization): ?><option value="<?= (int) $organization['id'] ?>"><?= htmlspecialchars($organization['name']) ?></option><?php endforeach; ?></select></label><button class="button primary" type="submit">Créer l’invitation</button></form></article>
