<section class="panel entity-list-panel"><div class="panel-head"><div><h2>Répertoire des organisations</h2><p class="panel-subtitle">Structure, présence SaaS et mode de gestion des projets.</p></div><span class="chip"><?= count($organizations) ?> organisation<?= count($organizations)>1?'s':'' ?></span></div><div class="table-wrap"><table class="data-table entity-table"><thead><tr><th>Organisation</th><th>Type</th><th>Présence SaaS</th><th>Mode projets</th><th>Identifiant</th><th>Statut</th></tr></thead><tbody><?php foreach ($organizations as $organization): ?><tr><td><div class="entity-identity"><span class="entity-avatar"><?= htmlspecialchars(strtoupper(substr((string)$organization['name'],0,1))) ?></span><strong><?= htmlspecialchars($organization['name']) ?></strong></div></td><td><?= htmlspecialchars($organization['account_type']) ?></td><td><span class="status-badge"><?= htmlspecialchars($organization['registration_state']) ?></span></td><td><?= htmlspecialchars($organization['project_mode']) ?></td><td><code><?= htmlspecialchars($organization['slug']) ?></code></td><td><span class="status-badge"><?= htmlspecialchars($organization['status']) ?></span></td></tr><?php endforeach; ?><?php if(empty($organizations)): ?><tr><td colspan="6"><div class="empty-state">Aucune organisation enregistrée.</div></td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel entity-list-panel"><div class="panel-head"><div><h2>Utilisateurs et memberships</h2><p class="panel-subtitle">Rôles et état des accès pour chaque organisation.</p></div><span class="chip"><?= count($memberships) ?> membre<?= count($memberships)>1?'s':'' ?></span></div><div class="table-wrap"><table class="data-table entity-table"><thead><tr><th>Utilisateur</th><th>Organisation</th><th>Rôle et statut</th></tr></thead><tbody><?php foreach ($memberships as $membership): ?><tr><td><div class="entity-contact"><strong><?= htmlspecialchars($membership['nom']) ?></strong><small><?= htmlspecialchars($membership['email']) ?></small></div></td><td><?= htmlspecialchars($membership['organization_name'] ?? 'Équipe interne') ?></td><td><form method="post" class="mini-inline-form membership-form"><input type="hidden" name="action" value="update_membership"><input type="hidden" name="membership_id" value="<?= (int)$membership['id'] ?>"><select name="membership_role" aria-label="Rôle"><?php foreach(['Owner','Admin','Manager','Member','Client'] as $role): ?><option value="<?= $role ?>" <?= $membership['membership_role']===$role?'selected':'' ?>><?= $role ?></option><?php endforeach; ?></select><select name="membership_status" aria-label="Statut"><?php foreach(['Invite','Actif','Suspendu'] as $status): ?><option value="<?= $status ?>" <?= $membership['status']===$status?'selected':'' ?>><?= $status ?></option><?php endforeach; ?></select><button class="button secondary button-small" type="submit">Mettre à jour</button></form></td></tr><?php endforeach; ?><?php if(empty($memberships)): ?><tr><td colspan="3"><div class="empty-state">Aucun utilisateur rattaché.</div></td></tr><?php endif; ?></tbody></table></div></section>